package com.personal.assistant.module.automation.service;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.personal.assistant.common.exception.*;import com.personal.assistant.module.automation.dto.AutomationRuleRequest;import com.personal.assistant.module.automation.entity.*;import com.personal.assistant.module.automation.mapper.*;import org.springframework.dao.DuplicateKeyException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Service public class AutomationService{private static final Set<String>TRIGGERS=Set.of("TASK_DUE","TASK_OVERDUE","INBOX_KEYWORD","BILL_THRESHOLD","UNCATEGORIZED_BILL","FIXED_TIME","WORKDAY_TIME");private static final Set<String>ACTIONS=Set.of("CREATE_REMINDER","CREATE_TASK","SEND_NOTIFICATION","GENERATE_REPORT","ADD_INBOX");private static final ZoneId SHANGHAI=ZoneId.of("Asia/Shanghai");private final AutomationRuleMapper rules;private final AutomationExecutionMapper executions;private final ObjectMapper json;private final JdbcTemplate jdbc;private final AutomationActionService actions;
 public AutomationService(AutomationRuleMapper rules,AutomationExecutionMapper executions,ObjectMapper json,JdbcTemplate jdbc,AutomationActionService actions){this.rules=rules;this.executions=executions;this.json=json;this.jdbc=jdbc;this.actions=actions;}
 public List<AutomationRule>list(Long uid){return rules.selectList(new LambdaQueryWrapper<AutomationRule>().eq(AutomationRule::getUserId,uid).orderByDesc(AutomationRule::getUpdatedAt));}public List<AutomationExecution>logs(Long uid,Long ruleId){owned(uid,ruleId);return executions.selectList(new LambdaQueryWrapper<AutomationExecution>().eq(AutomationExecution::getUserId,uid).eq(AutomationExecution::getRuleId,ruleId).orderByDesc(AutomationExecution::getStartedAt).last("limit 200"));}
 @Transactional public Long create(Long uid,AutomationRuleRequest r){validate(r);AutomationRule x=new AutomationRule();apply(x,r);x.setUserId(uid);x.setCreatedAt(now());x.setUpdatedAt(now());x.setNextRunAt(nextRun(x,now()));rules.insert(x);return x.getId();}@Transactional public void update(Long uid,Long id,AutomationRuleRequest r){validate(r);AutomationRule x=owned(uid,id);apply(x,r);x.setUpdatedAt(now());x.setNextRunAt(nextRun(x,now()));rules.updateById(x);}@Transactional public void toggle(Long uid,Long id,boolean enabled){AutomationRule x=owned(uid,id);x.setEnabled(enabled);x.setUpdatedAt(now());x.setNextRunAt(enabled?nextRun(x,now()):null);rules.updateById(x);}@Transactional public void delete(Long uid,Long id){rules.deleteById(owned(uid,id).getId());}
 public void runNow(Long uid,Long id){execute(owned(uid,id),true);}@Scheduled(fixedDelay=60000)public void scan(){LocalDateTime at=now();rules.selectList(new LambdaQueryWrapper<AutomationRule>().eq(AutomationRule::getEnabled,true).and(q->q.isNull(AutomationRule::getNextRunAt).or().le(AutomationRule::getNextRunAt,at)).last("limit 200")).forEach(rule->execute(rule,false));}
 private void execute(AutomationRule rule,boolean manual){LocalDateTime started=now();List<Source>sources=findSources(rule);if(sources.isEmpty())sources=List.of(new Source("SCHEDULE",started.toLocalDate().toString(),"定时触发"));String finalStatus="SKIPPED";for(Source source:sources){String key=rule.getId()+":"+source.type+":"+source.id+":"+(manual?"manual:"+started:bucket(rule,started));AutomationExecution log=new AutomationExecution();log.setUserId(rule.getUserId());log.setRuleId(rule.getId());log.setSourceType(source.type);log.setSourceId(source.id);log.setIdempotencyKey(key);log.setStatus("RUNNING");log.setAttemptCount(1);log.setStartedAt(started);try{executions.insert(log);}catch(DuplicateKeyException e){continue;}try{Long result=actions.act(rule.getUserId(),rule.getName(),rule.getActionType(),map(rule.getActionConfig()),source.title,now());log.setResultType(rule.getActionType());log.setResultId(result);log.setStatus("SUCCESS");finalStatus="SUCCESS";}catch(Exception e){log.setStatus("FAILED");log.setFailureReason(e.getMessage());finalStatus="FAILED";}finally{log.setFinishedAt(now());executions.updateById(log);}}rule.setLastRunAt(started);rule.setLastStatus(finalStatus);rule.setNextRunAt(nextRun(rule,started.plusMinutes(1)));rule.setUpdatedAt(now());rules.updateById(rule);}
 private List<Source>findSources(AutomationRule r){Map<String,Object>cfg=map(r.getTriggerConfig());String type=r.getTriggerType();if(type.endsWith("TIME"))return List.of();if("TASK_DUE".equals(type)||"TASK_OVERDUE".equals(type)){int minutes=number(cfg.get("minutes"),60);String op="TASK_OVERDUE".equals(type)?"plan_time < ?":"plan_time between ? and ?";LocalDateTime at=now();Object[]args="TASK_OVERDUE".equals(type)?new Object[]{r.getUserId(),at}:new Object[]{r.getUserId(),at,at.plusMinutes(minutes)};return jdbc.query("select id,title from task_item where user_id=? and archived=false and status not in ('DONE','COMPLETED','ARCHIVED') and "+op,(rs,n)->new Source("TASK",String.valueOf(rs.getLong("id")),rs.getString("title")),args);}if("INBOX_KEYWORD".equals(type)){String keyword=String.valueOf(cfg.getOrDefault("keyword",""));return jdbc.query("select id,content from inbox_item where user_id=? and status='PENDING' and content like ?",(rs,n)->new Source("INBOX",String.valueOf(rs.getLong("id")),rs.getString("content")),r.getUserId(),"%"+keyword+"%");}if("BILL_THRESHOLD".equals(type)){BigDecimal amount=new BigDecimal(String.valueOf(cfg.getOrDefault("amount","0")));return jdbc.query("select id,description from finance_transaction where user_id=? and amount>=? and transaction_time>=?",(rs,n)->new Source("BILL",String.valueOf(rs.getLong("id")),rs.getString("description")),r.getUserId(),amount,now().minusDays(1));}if("UNCATEGORIZED_BILL".equals(type))return jdbc.query("select id,description from finance_transaction where user_id=? and category_id is null and transaction_time>=?",(rs,n)->new Source("BILL",String.valueOf(rs.getLong("id")),rs.getString("description")),r.getUserId(),now().minusDays(number(cfg.get("days"),3)));return List.of();}
 private void apply(AutomationRule x,AutomationRuleRequest r){try{x.setName(r.name().trim());x.setEnabled(!Boolean.FALSE.equals(r.enabled()));x.setTriggerType(r.triggerType());x.setTriggerConfig(json.writeValueAsString(r.triggerConfig()));x.setConditionConfig(json.writeValueAsString(r.conditionConfig()==null?Map.of():r.conditionConfig()));x.setActionType(r.actionType());x.setActionConfig(json.writeValueAsString(r.actionConfig()));x.setCooldownMinutes(Optional.ofNullable(r.cooldownMinutes()).orElse(0));}catch(Exception e){throw new IllegalArgumentException(e);}}private void validate(AutomationRuleRequest r){if(!TRIGGERS.contains(r.triggerType()))throw validation("触发类型不支持");if(!ACTIONS.contains(r.actionType()))throw validation("动作类型不支持");}
 private LocalDateTime nextRun(AutomationRule r,LocalDateTime from){if(!Boolean.TRUE.equals(r.getEnabled()))return null;if(!Set.of("FIXED_TIME","WORKDAY_TIME").contains(r.getTriggerType()))return from.plusMinutes(Math.max(1,Optional.ofNullable(r.getCooldownMinutes()).orElse(0)));LocalTime time=LocalTime.parse(String.valueOf(map(r.getTriggerConfig()).getOrDefault("time","09:00")));LocalDateTime next=from.toLocalDate().atTime(time);if(!next.isAfter(from))next=next.plusDays(1);if("WORKDAY_TIME".equals(r.getTriggerType()))while(next.getDayOfWeek().getValue()>5)next=next.plusDays(1);return next;}
 private AutomationRule owned(Long uid,Long id){AutomationRule x=rules.selectById(id);if(x==null||!uid.equals(x.getUserId()))throw new BusinessException(ErrorCode.NOT_FOUND,"自动化规则不存在");return x;}private Map<String,Object>map(String value){try{return json.readValue(value,new TypeReference<>(){});}catch(Exception e){return new HashMap<>();}}private String bucket(AutomationRule r,LocalDateTime at){int cool=Math.max(1,Optional.ofNullable(r.getCooldownMinutes()).orElse(1));return String.valueOf(at.atZone(SHANGHAI).toEpochSecond()/(cool*60L));}private int number(Object v,int d){try{return v==null?d:Integer.parseInt(String.valueOf(v));}catch(Exception e){return d;}}private LocalDateTime now(){return LocalDateTime.now(SHANGHAI);}private BusinessException validation(String m){return new BusinessException(ErrorCode.VALIDATION_ERROR,m);}private record Source(String type,String id,String title){}
}
